class ApiResource {
  const ApiResource({
    required this.path,
    required this.description,
    required this.module,
    required this.category,
    required this.methods,
    required this.filters,
  });

  final String path;
  final String description;
  final String module;
  final String category;
  final List<String> methods;
  final List<String> filters;

  bool get canRead => methods.contains('GET');
  bool get canCreate => methods.contains('POST');
  bool get canUpdate => methods.contains('PATCH') || methods.contains('PUT');
  bool get canDelete => methods.contains('DELETE');
  bool get readOnly => !canCreate && !canUpdate && !canDelete;

  /// Human name from the path: /year-groups -> Year groups.
  String get title {
    final raw = path.substring(1).replaceAll('-', ' ');
    return raw.isEmpty ? raw : raw[0].toUpperCase() + raw.substring(1);
  }

  /// The gibbon table this resource is generated from, when the filters
  /// reveal it (gibbonYearGroup.name -> gibbonYearGroup).
  String? get primaryTable {
    for (final f in filters) {
      final dot = f.indexOf('.');
      if (dot > 0) return f.substring(0, dot);
    }
    return null;
  }
}

